static int usb_write(void *context,const uint8_t *bytes,size_t length,uint32_t timeout_ms){(void)timeout_ms;usb_fake_t*f=context;pthread_mutex_lock(&f->mutex);assert(f->output_count+length<=sizeof(f->output));memcpy(f->output+f->output_count,bytes,length);f->output_count+=length;pthread_mutex_unlock(&f->mutex);return(int)length;}
